    zh: {
      'tab.title': 'SSH',
      'panel.title': 'SSH',
      'spike.title': 'SSH 插件 · 传输探针',
    },
    en: {
      'tab.title': 'SSH',
      'panel.title': 'SSH',
      'spike.title': 'SSH plugin · transport spike',
    },
